      music = "PW_5_Suspect",
      renwu = "npc",
      sentence = "Holding the imperial jade seal aloft, with a sword in one hand, he stood shouting in the palace hall, but all around no one heeded him. Sunlight shone into the hall all warm and cheery, without a bit of bleakness.",
