      beijing = 4490,
      bganim = 0,
      dialog = 3,
      music = "PW_5_Suspect",
      renwu = "npc",
      sentence = "Victor walked over, slowly and steadily. He gave his longbow to a nearby official, then walked empty-handed up to Lord Chen, who was holding the blade.",
