    [18] = {
      beijing = 4490,
      dialog = 3,
      music = "PW_5_Suspect",
      renwu = "npc",
      sentence = "But Lord Chen didn't dare do anything. With every step forward Victor took, he stumbled back two. When Victor had approached the throne, Lord Chen had backed up to the bottom of the stairs.",
