      renwu = "npc",
      role1 = 1112000,
      role2 = 1112102,
      role3 = 102201,
      role5 = 1112402,
      sentence = "I looked down and examined the arrow in his hand and suddenly realized — crimson feathers, a hooked tip... this was the kind that Lord Chen's army used.",
