      role1 = 1112000,
      role2 = 1112104,
      role3 = 102203,
      role5 = 1112402,
      sentence = "Victor looked at me as layers of light and shadow played across his eyes. The chilling, murderous look from when he stood outside the city with the sword in his hand was all gone, replaced by the now tender and warm brow.",
