      renwu = "npc",
      role1 = 1112000,
      role2 = 1112102,
      role3 = 102201,
      role5 = 1112402,
      sentence = "He didn't say another word. And he didn't need to say anything. Whether Lord Chen was killed or not, the old grudge had been avenged — I truly didn't need to go on weighing myself down with it.",
