    },
    [35] = {
      beijing = 1601,
      bganim = 0,
      dialog = 3,
      music = "28_Double_Seventh02",
      renwu = "npc",
      sentence = "I let him lead me along under the mild winter sunshine. Each beam of light hitting our faces felt like warmth from a fire from which a phoenix had risen.",
