    },
    [36] = {
      beijing = 1601,
      dhead = 1211,
      dialog = 1,
      music = "28_Double_Seventh02",
      renming = "$u",
      renwu = "npc",
      sentence = "Five years of war and bringing peace to the world, and the first thing you want to do after reclaiming the throne is to bask in some sun?",
