      renwu = "npc",
      role1 = 1112000,
      role2 = 1112102,
      role3 = 102201,
      role5 = 1112402,
      sentence = "He turned his head and pulled me into the rockwork of the garden. I followed curiously, and tugged questioningly on Victor's hand.",
