    },
    [49] = {
      beijing = 1601,
      dialog = 3,
      music = "28_Double_Seventh02",
      renwu = "npc",
      sentence = "That year, my father led troops and fought off the incursions from the desert tribes of the north. He came to Unipolis to receive a reward.",
      next = {50}
    },
    [50] = {
      beijing = 1601,
      dialog = 3,
      music = "28_Double_Seventh02",
      renwu = "npc",
      sentence = "The visit coincided with the fall hunt, and the former emperor, hearing that I had practically grown up on horseback, made a special provision for me to take part in the palace horse race. I was chomping at the bit and wanted nothing more than to take first place.",
      next = {51}
    },
    [51] = {
      beijing = 1601,
      dhead = 1207,
      dialog = 1,
      music = "28_Double_Seventh02",
      renming = "$u",
      renwu = "npc",
      sentence = "At first it was just for bragging rights... but then the former emperor said that the winner would be bestowed a prized thoroughbred that was given as a tribute from a foreign land.",
      next = {52}
    },
    [52] = {
      beijing = 1601,
      dialog = 3,
      music = "28_Double_Seventh02",
      renwu = "npc",
      role1 = 1112000,
      role2 = 1112102,
      role3 = 102201,
      role5 = 1112402,
      ruchang = -1,
      sentence = "Victor diffidently lowered his eyes and spoke in a soft, soothing voice as if to comfort me.",
