    [54] = {
      beijing = 1601,
      dhead = 1208,
      dialog = 1,
      music = "28_Double_Seventh02",
      renming = "$u",
      renwu = "npc",
      sentence = "At the time my father lectured me, saying that I was under no circumstances to beat the palace princes, especially since I was a girl.",
      next = {55}
    },
    [55] = {
      beijing = 1601,
      dhead = 1208,
      dialog = 1,
      music = "28_Double_Seventh02",
      renming = "$u",
      renwu = "npc",
      sentence = "If they lost to me, how could they keep face?",
