      dhead = 1208,
      dialog = 1,
      music = "28_Double_Seventh02",
      renming = "$u",
      renwu = "npc",
      sentence = "In a fit of anger, I hid the horsewhip here and told the people in the palace that I'd lost it and couldn't compete.",
