      dhead = 1201,
      dialog = 1,
      music = "28_Double_Seventh02",
      renming = "$u",
      renwu = "npc",
      sentence = "How could a subject ever compete with the royals?",
      next = {61}
    },
    [61] = {
      beijing = 1601,
      dialog = 3,
      music = "28_Double_Seventh02",
      renwu = "npc",
      sentence = "My gaze froze for a moment, then I laughed again.",
